import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import axios from "axios";

const EARTH_RADIUS = 100;
const DEBRIS_API = "http://localhost:5000/api/debris";
const ISS_API = "http://localhost:5000/iss";

const EarthScene = ({ onBack }) => {
  const mountRef = useRef(null);

  const [telemetry, setTelemetry] = useState({
    debrisCount: 0,
    selected: null,
    iss: null,
    connected: false,
    lastUpdate: null,
    error: null,
  });

  const [viewMode, setViewMode] = useState("TRACKING");

  useEffect(() => {
    const mount = mountRef.current;

    if (!mount) return;

    let disposed = false;

    /* =========================================================
       THREE.JS SETUP
    ========================================================= */

    const width = mount.clientWidth || window.innerWidth;
    const height = mount.clientHeight || window.innerHeight;

    const scene = new THREE.Scene();

    scene.background = new THREE.Color(0x010409);

    const camera = new THREE.PerspectiveCamera(
      45,
      width / height,
      0.1,
      5000
    );

    camera.position.set(0, 160, 430);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance",
    });

    renderer.setPixelRatio(
      Math.min(window.devicePixelRatio || 1, 2)
    );

    renderer.setSize(width, height);
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    mount.appendChild(renderer.domElement);

    /* =========================================================
       CONTROLS
    ========================================================= */

    const controls = new OrbitControls(
      camera,
      renderer.domElement
    );

    controls.enableDamping = true;
    controls.dampingFactor = 0.06;

    controls.enablePan = false;

    controls.minDistance = 125;
    controls.maxDistance = 900;

    controls.target.set(0, 0, 0);

    /* =========================================================
       LIGHTING
    ========================================================= */

    const ambientLight = new THREE.AmbientLight(
      0xffffff,
      0.38
    );

    scene.add(ambientLight);

    const sunLight = new THREE.DirectionalLight(
      0xffffff,
      2.1
    );

    sunLight.position.set(450, 250, 400);

    scene.add(sunLight);

    const rimLight = new THREE.DirectionalLight(
      0x4cc9ff,
      0.45
    );

    rimLight.position.set(-350, 50, -300);

    scene.add(rimLight);

    /* =========================================================
       TEXTURES
    ========================================================= */

    const loader = new THREE.TextureLoader();

    const earthTexture = loader.load(
      "/textures/earth_atmos_2048.jpg"
    );

    const cloudTexture = loader.load(
      "/textures/earth_clouds_1024.png"
    );

    /* =========================================================
       EARTH
    ========================================================= */

    const earthGroup = new THREE.Group();

    scene.add(earthGroup);

    const earthGeometry = new THREE.SphereGeometry(
      EARTH_RADIUS,
      96,
      96
    );

    const earthMaterial = new THREE.MeshPhongMaterial({
      map: earthTexture,
      shininess: 12,
      specular: new THREE.Color(0x1b4055),
    });

    const earth = new THREE.Mesh(
      earthGeometry,
      earthMaterial
    );

    earthGroup.add(earth);

    /* =========================================================
       CLOUDS
    ========================================================= */

    const cloudGeometry = new THREE.SphereGeometry(
      EARTH_RADIUS + 2.1,
      72,
      72
    );

    const cloudMaterial = new THREE.MeshPhongMaterial({
      map: cloudTexture,
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
    });

    const clouds = new THREE.Mesh(
      cloudGeometry,
      cloudMaterial
    );

    earthGroup.add(clouds);

    /* =========================================================
       ATMOSPHERE
    ========================================================= */

    const atmosphereGeometry =
      new THREE.SphereGeometry(
        EARTH_RADIUS + 5,
        64,
        64
      );

    const atmosphereMaterial =
      new THREE.MeshBasicMaterial({
        color: 0x39bdf8,
        transparent: true,
        opacity: 0.055,
        side: THREE.BackSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });

    const atmosphere = new THREE.Mesh(
      atmosphereGeometry,
      atmosphereMaterial
    );

    earthGroup.add(atmosphere);

    /* =========================================================
       STAR FIELD
    ========================================================= */

    const starGeometry = new THREE.BufferGeometry();

    const starCount = 18000;

    const starPositions = new Float32Array(
      starCount * 3
    );

    for (let i = 0; i < starCount; i++) {
      const radius =
        1500 + Math.random() * 3000;

      const theta =
        Math.random() * Math.PI * 2;

      const phi =
        Math.acos(
          2 * Math.random() - 1
        );

      const x =
        radius *
        Math.sin(phi) *
        Math.cos(theta);

      const y =
        radius *
        Math.cos(phi);

      const z =
        radius *
        Math.sin(phi) *
        Math.sin(theta);

      starPositions[i * 3] = x;
      starPositions[i * 3 + 1] = y;
      starPositions[i * 3 + 2] = z;
    }

    starGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(
        starPositions,
        3
      )
    );

    const starMaterial =
      new THREE.PointsMaterial({
        color: 0xffffff,
        size: 0.65,
        transparent: true,
        opacity: 0.72,
        sizeAttenuation: true,
      });

    const stars = new THREE.Points(
      starGeometry,
      starMaterial
    );

    scene.add(stars);

    /* =========================================================
       ORBITAL REFERENCE RINGS
    ========================================================= */

    const orbitGroup = new THREE.Group();

    scene.add(orbitGroup);

    const createOrbitRing = (
      radius,
      rotationX,
      rotationZ,
      opacity = 0.16
    ) => {
      const points = [];

      for (let i = 0; i <= 128; i++) {
        const angle =
          (i / 128) * Math.PI * 2;

        points.push(
          new THREE.Vector3(
            radius * Math.cos(angle),
            0,
            radius * Math.sin(angle)
          )
        );
      }

      const geometry =
        new THREE.BufferGeometry().setFromPoints(
          points
        );

      const material =
        new THREE.LineBasicMaterial({
          color: 0x3da8d8,
          transparent: true,
          opacity,
        });

      const ring = new THREE.LineLoop(
        geometry,
        material
      );

      ring.rotation.x = rotationX;
      ring.rotation.z = rotationZ;

      orbitGroup.add(ring);

      return ring;
    };

    createOrbitRing(
      122,
      THREE.MathUtils.degToRad(12),
      THREE.MathUtils.degToRad(20),
      0.13
    );

    createOrbitRing(
      145,
      THREE.MathUtils.degToRad(42),
      THREE.MathUtils.degToRad(-30),
      0.1
    );

    createOrbitRing(
      175,
      THREE.MathUtils.degToRad(72),
      THREE.MathUtils.degToRad(50),
      0.075
    );

    createOrbitRing(
      215,
      THREE.MathUtils.degToRad(25),
      THREE.MathUtils.degToRad(80),
      0.06
    );

    /* =========================================================
       DEBRIS
    ========================================================= */

    const debrisGroup = new THREE.Group();

    scene.add(debrisGroup);

    const debrisGeometry =
      new THREE.SphereGeometry(
        1.55,
        8,
        8
      );

    const debrisMaterial =
      new THREE.MeshStandardMaterial({
        color: 0x55d9ff,
        emissive: 0x073a4f,
        emissiveIntensity: 1.7,
        roughness: 0.4,
        metalness: 0.3,
      });

    let debrisMesh = null;
    let debrisData = [];

    /* =========================================================
       ISS
    ========================================================= */

    const issGroup = new THREE.Group();

    scene.add(issGroup);

    const issGeometry =
      new THREE.SphereGeometry(
        3.6,
        20,
        20
      );

    const issMaterial =
      new THREE.MeshStandardMaterial({
        color: 0xff3b30,
        emissive: 0x6e0b05,
        emissiveIntensity: 2,
      });

    const iss = new THREE.Mesh(
      issGeometry,
      issMaterial
    );

    issGroup.add(iss);

    const issGlowGeometry =
      new THREE.SphereGeometry(
        6,
        16,
        16
      );

    const issGlowMaterial =
      new THREE.MeshBasicMaterial({
        color: 0xff3b30,
        transparent: true,
        opacity: 0.11,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });

    const issGlow = new THREE.Mesh(
      issGlowGeometry,
      issGlowMaterial
    );

    issGroup.add(issGlow);

    /* =========================================================
       COORDINATE CONVERSION
    ========================================================= */

    const convertCoordsToVector = (
      lat,
      lon,
      alt
    ) => {
      const safeLat = Number(lat) || 0;
      const safeLon = Number(lon) || 0;
      const safeAlt = Number(alt) || 0;

      /*
       * The API altitude is assumed to be kilometers.
       *
       * The visualization compresses altitude so that
       * high-orbit objects remain visible around Earth.
       */
      const visualAltitude =
        Math.max(
          10,
          Math.min(
            260,
            safeAlt / 1000
          )
        );

      const radius =
        EARTH_RADIUS +
        visualAltitude;

      const phi =
        (90 - safeLat) *
        (Math.PI / 180);

      const theta =
        (safeLon + 180) *
        (Math.PI / 180);

      return new THREE.Vector3(
        -radius *
          Math.sin(phi) *
          Math.cos(theta),

        radius *
          Math.cos(phi),

        radius *
          Math.sin(phi) *
          Math.sin(theta)
      );
    };

    /* =========================================================
       SELECTED OBJECT HIGHLIGHT
    ========================================================= */

    let selectedMarker = null;

    const createSelectedMarker = () => {
      const group = new THREE.Group();

      const ringGeometry =
        new THREE.RingGeometry(
          4,
          4.7,
          32
        );

      const ringMaterial =
        new THREE.MeshBasicMaterial({
          color: 0xffffff,
          transparent: true,
          opacity: 0.9,
          side: THREE.DoubleSide,
        });

      const ring = new THREE.Mesh(
        ringGeometry,
        ringMaterial
      );

      group.add(ring);

      const innerGeometry =
        new THREE.SphereGeometry(
          2.4,
          12,
          12
        );

      const innerMaterial =
        new THREE.MeshBasicMaterial({
          color: 0xffffff,
        });

      const inner =
        new THREE.Mesh(
          innerGeometry,
          innerMaterial
        );

      group.add(inner);

      group.visible = false;

      scene.add(group);

      return group;
    };

    selectedMarker =
      createSelectedMarker();

    /* =========================================================
       SELECTED OBJECT ORBIT
    ========================================================= */

    let selectedOrbit = null;

    const clearSelectedOrbit = () => {
      if (selectedOrbit) {
        scene.remove(selectedOrbit);

        selectedOrbit.geometry.dispose();
        selectedOrbit.material.dispose();

        selectedOrbit = null;
      }
    };

    const createSelectedOrbit = (
      position
    ) => {
      clearSelectedOrbit();

      const direction =
        position.clone().normalize();

      const reference =
        Math.abs(direction.y) < 0.9
          ? new THREE.Vector3(
              0,
              1,
              0
            )
          : new THREE.Vector3(
              1,
              0,
              0
            );

      const axisA =
        new THREE.Vector3()
          .crossVectors(
            direction,
            reference
          )
          .normalize();

      const axisB =
        new THREE.Vector3()
          .crossVectors(
            direction,
            axisA
          )
          .normalize();

      const radius =
        Math.max(
          125,
          position.length()
        );

      const points = [];

      for (
        let i = 0;
        i <= 128;
        i++
      ) {
        const angle =
          (i / 128) *
          Math.PI *
          2;

        const point =
          new THREE.Vector3()
            .addScaledVector(
              axisA,
              radius *
                Math.cos(angle)
            )
            .addScaledVector(
              axisB,
              radius *
                0.46 *
                Math.sin(angle)
            );

        points.push(point);
      }

      const geometry =
        new THREE.BufferGeometry().setFromPoints(
          points
        );

      const material =
        new THREE.LineBasicMaterial({
          color: 0xffffff,
          transparent: true,
          opacity: 0.48,
        });

      selectedOrbit =
        new THREE.LineLoop(
          geometry,
          material
        );

      scene.add(selectedOrbit);
    };

    /* =========================================================
       LOAD DEBRIS
    ========================================================= */

    const updateDebris = async () => {
      try {
        const response =
          await axios.get(
            DEBRIS_API
          );

        if (disposed) return;

        const data = Array.isArray(
          response.data
        )
          ? response.data
          : [];

        debrisData = data;

        /*
         * Dispose previous mesh.
         * The whole group is kept, but the old geometry
         * is removed before creating the new InstancedMesh.
         */
        if (debrisMesh) {
          debrisGroup.remove(
            debrisMesh
          );

          debrisMesh.dispose?.();

          debrisMesh = null;
        }

        if (data.length > 0) {
          debrisMesh =
            new THREE.InstancedMesh(
              debrisGeometry,
              debrisMaterial,
              data.length
            );

          const matrix =
            new THREE.Matrix4();

          data.forEach(
            (item, index) => {
              const position =
                convertCoordsToVector(
                  item.lat,
                  item.lon,
                  item.alt
                );

              matrix.makeTranslation(
                position.x,
                position.y,
                position.z
              );

              debrisMesh.setMatrixAt(
                index,
                matrix
              );
            }
          );

          debrisMesh.instanceMatrix.needsUpdate =
            true;

          debrisMesh.frustumCulled =
            false;

          debrisGroup.add(
            debrisMesh
          );
        }

        setTelemetry(
          (previous) => ({
            ...previous,
            debrisCount:
              data.length,
            connected: true,
            error: null,
            lastUpdate:
              new Date(),
          })
        );
      } catch (error) {
        console.error(
          "Debris telemetry error:",
          error
        );

        setTelemetry(
          (previous) => ({
            ...previous,
            connected: false,
            error:
              "Unable to connect to debris telemetry.",
          })
        );
      }
    };

    /* =========================================================
       ISS UPDATE
    ========================================================= */

    const updateISS = async () => {
      try {
        const response =
          await axios.get(
            ISS_API
          );

        if (disposed) return;

        const {
          lat,
          lon,
          alt,
        } = response.data || {};

        const position =
          convertCoordsToVector(
            lat,
            lon,
            alt
          );

        iss.position.copy(
          position
        );

        issGlow.position.copy(
          position
        );

        setTelemetry(
          (previous) => ({
            ...previous,
            iss: {
              lat,
              lon,
              alt,
            },
          })
        );
      } catch (error) {
        console.error(
          "ISS tracking error:",
          error
        );
      }
    };

    updateDebris();
    updateISS();

    const debrisInterval =
      setInterval(
        updateDebris,
        5000
      );

    const issInterval =
      setInterval(
        updateISS,
        5000
      );

    /* =========================================================
       RAYCASTER
    ========================================================= */

    const raycaster =
      new THREE.Raycaster();

    const pointer =
      new THREE.Vector2();

    const handlePointerClick =
      (event) => {
        if (!debrisMesh) return;

        const rect =
          renderer.domElement.getBoundingClientRect();

        pointer.x =
          ((event.clientX -
            rect.left) /
            rect.width) *
            2 -
          1;

        pointer.y =
          -(
            (event.clientY -
              rect.top) /
              rect.height
          ) *
            2 +
          1;

        raycaster.setFromCamera(
          pointer,
          camera
        );

        const intersections =
          raycaster.intersectObject(
            debrisMesh
          );

        if (
          !intersections.length
        ) {
          selectedMarker.visible =
            false;

          clearSelectedOrbit();

          setTelemetry(
            (previous) => ({
              ...previous,
              selected: null,
            })
          );

          return;
        }

        const hit =
          intersections[0];

        const instanceId =
          hit.instanceId;

        if (
          instanceId === undefined ||
          !debrisData[instanceId]
        ) {
          return;
        }

        const object =
          debrisData[instanceId];

        const position =
          convertCoordsToVector(
            object.lat,
            object.lon,
            object.alt
          );

        selectedMarker.position.copy(
          position
        );

        selectedMarker.visible =
          true;

        createSelectedOrbit(
          position
        );

        setTelemetry(
          (previous) => ({
            ...previous,
            selected: {
              ...object,
              index:
                instanceId + 1,
            },
          })
        );
      };

    renderer.domElement.addEventListener(
      "click",
      handlePointerClick
    );

    /* =========================================================
       CAMERA RESET
    ========================================================= */

    const resetCamera =
      () => {
        camera.position.set(
          0,
          160,
          430
        );

        controls.target.set(
          0,
          0,
          0
        );

        controls.update();
      };

    /* =========================================================
       VIEW MODES
    ========================================================= */

    const handleViewChange =
      (mode) => {
        setViewMode(mode);

        if (
          mode === "EARTH"
        ) {
          camera.position.set(
            0,
            30,
            250
          );

          controls.target.set(
            0,
            0,
            0
          );
        }

        if (
          mode === "TRACKING"
        ) {
          camera.position.set(
            0,
            160,
            430
          );

          controls.target.set(
            0,
            0,
            0
          );
        }

        if (
          mode === "WIDE"
        ) {
          camera.position.set(
            0,
            280,
            700
          );

          controls.target.set(
            0,
            0,
            0
          );
        }

        controls.update();
      };

    /* =========================================================
       EXPOSE CONTROLS TO UI
    ========================================================= */

    mount.__resetCamera =
      resetCamera;

    mount.__changeView =
      handleViewChange;

    /* =========================================================
       ANIMATION
    ========================================================= */

    let animationFrame;

    const animate =
      () => {
        if (disposed) return;

        animationFrame =
          requestAnimationFrame(
            animate
          );

        earth.rotation.y +=
          0.00018;

        clouds.rotation.y +=
          0.00028;

        stars.rotation.y +=
          0.000015;

        orbitGroup.rotation.y +=
          0.00008;

        if (
          selectedMarker &&
          selectedMarker.visible
        ) {
          selectedMarker.rotation.z +=
            0.012;

          const pulse =
            1 +
            Math.sin(
              performance.now() *
                0.005
            ) *
              0.12;

          selectedMarker.scale.set(
            pulse,
            pulse,
            pulse
          );
        }

        issGlow.scale.setScalar(
          1 +
            Math.sin(
              performance.now() *
                0.004
            ) *
              0.12
        );

        controls.update();

        renderer.render(
          scene,
          camera
        );
      };

    animate();

    /* =========================================================
       RESIZE
    ========================================================= */

    const handleResize =
      () => {
        if (!mount) return;

        const newWidth =
          mount.clientWidth ||
          window.innerWidth;

        const newHeight =
          mount.clientHeight ||
          window.innerHeight;

        camera.aspect =
          newWidth / newHeight;

        camera.updateProjectionMatrix();

        renderer.setSize(
          newWidth,
          newHeight
        );
      };

    window.addEventListener(
      "resize",
      handleResize
    );

    /* =========================================================
       CLEANUP
    ========================================================= */

    return () => {
      disposed = true;

      cancelAnimationFrame(
        animationFrame
      );

      clearInterval(
        debrisInterval
      );

      clearInterval(
        issInterval
      );

      window.removeEventListener(
        "resize",
        handleResize
      );

      renderer.domElement.removeEventListener(
        "click",
        handlePointerClick
      );

      controls.dispose();

      clearSelectedOrbit();

      earthGeometry.dispose();
      earthMaterial.dispose();

      cloudGeometry.dispose();
      cloudMaterial.dispose();

      atmosphereGeometry.dispose();
      atmosphereMaterial.dispose();

      starGeometry.dispose();
      starMaterial.dispose();

      debrisGeometry.dispose();
      debrisMaterial.dispose();

      issGeometry.dispose();
      issMaterial.dispose();

      issGlowGeometry.dispose();
      issGlowMaterial.dispose();

      renderer.dispose();

      if (
        mount &&
        renderer.domElement.parentNode ===
          mount
      ) {
        mount.removeChild(
          renderer.domElement
        );
      }
    };
  }, []);

  /* =========================================================
     UI HELPERS
  ========================================================= */

  const formatTime = () => {
    if (!telemetry.lastUpdate) {
      return "--:--:--";
    }

    return telemetry.lastUpdate.toLocaleTimeString(
      [],
      {
        hour12: false,
      }
    );
  };

  const selected =
    telemetry.selected;

  return (
    <div className="earth-tracker">
      {/* =========================
          3D SCENE
      ========================== */}

      <div
        ref={mountRef}
        className="earth-canvas"
      />

      {/* =========================
          TOP HUD
      ========================== */}

      <header className="tracker-topbar">
        <div className="tracker-brand">
          <button
            className="tracker-back"
            onClick={() => {
              if (onBack) {
                onBack();
              }
            }}
            title="Return to landing page"
          >
            ←
          </button>

          <div>
            <strong>ORBITAL</strong>
            <span>DEBRIS TRACKER</span>
          </div>
        </div>

        <div className="tracker-title">
          <span>EARTH ORBITAL MONITORING</span>
          <strong>LIVE TRACKING ENVIRONMENT</strong>
        </div>

        <div className="tracker-connection">
          <span
            className={
              telemetry.connected
                ? "connection-dot online"
                : "connection-dot"
            }
          />

          <div>
            <strong>
              {telemetry.connected
                ? "SYSTEM ONLINE"
                : "SYSTEM OFFLINE"}
            </strong>

            <small>
              UPDATE {formatTime()}
            </small>
          </div>
        </div>
      </header>

      {/* =========================
          LEFT TELEMETRY PANEL
      ========================== */}

      <aside className="tracker-left-panel">
        <div className="hud-panel">
          <div className="hud-panel-title">
            <span>LIVE TELEMETRY</span>
            <small>01</small>
          </div>

          <div className="hud-stat">
            <span>TRACKED OBJECTS</span>
            <strong>
              {telemetry.debrisCount
                .toLocaleString()}
            </strong>
          </div>

          <div className="hud-stat">
            <span>ISS STATUS</span>
            <strong className="green">
              {telemetry.iss
                ? "TRACKED"
                : "SEARCHING"}
            </strong>
          </div>

          <div className="hud-stat">
            <span>FEED</span>
            <strong
              className={
                telemetry.connected
                  ? "green"
                  : "red"
              }
            >
              {telemetry.connected
                ? "LIVE"
                : "OFFLINE"}
            </strong>
          </div>
        </div>

        <div className="hud-panel legend-panel">
          <div className="hud-panel-title">
            <span>OBJECT LEGEND</span>
            <small>02</small>
          </div>

          <div className="legend-row">
            <span className="legend-dot debris-dot" />
            <span>SPACE DEBRIS</span>
          </div>

          <div className="legend-row">
            <span className="legend-dot iss-dot" />
            <span>INTERNATIONAL SPACE STATION</span>
          </div>

          <div className="legend-row">
            <span className="legend-line" />
            <span>REFERENCE ORBIT</span>
          </div>
        </div>
      </aside>

      {/* =========================
          RIGHT CONTROL PANEL
      ========================== */}

      <aside className="tracker-right-panel">
        <div className="hud-panel">
          <div className="hud-panel-title">
            <span>VIEW CONTROL</span>
            <small>03</small>
          </div>

          <button
            className={
              viewMode === "EARTH"
                ? "view-button active"
                : "view-button"
            }
            onClick={() =>
              mountRef.current?.__changeView(
                "EARTH"
              )
            }
          >
            Earth View
          </button>

          <button
            className={
              viewMode === "TRACKING"
                ? "view-button active"
                : "view-button"
            }
            onClick={() =>
              mountRef.current?.__changeView(
                "TRACKING"
              )
            }
          >
            Tracking View
          </button>

          <button
            className={
              viewMode === "WIDE"
                ? "view-button active"
                : "view-button"
            }
            onClick={() =>
              mountRef.current?.__changeView(
                "WIDE"
              )
            }
          >
            Wide Orbit
          </button>

          <button
            className="view-button reset"
            onClick={() =>
              mountRef.current?.__resetCamera()
            }
          >
            Reset Camera
          </button>
        </div>

        <div className="hud-panel">
          <div className="hud-panel-title">
            <span>CONTROLS</span>
            <small>04</small>
          </div>

          <p className="control-help">
            Drag to rotate
            <br />
            Scroll to zoom
            <br />
            Click an object to inspect
          </p>
        </div>
      </aside>

      {/* =========================
          SELECTED OBJECT
      ========================== */}

      {selected && (
        <div className="selected-object-panel">
          <div className="selected-header">
            <div>
              <span>SELECTED OBJECT</span>
              <strong>
                {selected.name ||
                  `OBJECT-${selected.index}`}
              </strong>
            </div>

            <button
              onClick={() => {
                mountRef.current?.click();
              }}
              aria-label="Close selected object"
            >
              ×
            </button>
          </div>

          <div className="selected-grid">
            <div>
              <span>LATITUDE</span>
              <strong>
                {Number(
                  selected.lat
                ).toFixed(2)}
                °
              </strong>
            </div>

            <div>
              <span>LONGITUDE</span>
              <strong>
                {Number(
                  selected.lon
                ).toFixed(2)}
                °
              </strong>
            </div>

            <div>
              <span>ALTITUDE</span>
              <strong>
                {Number(
                  selected.alt
                ).toFixed(2)}
                km
              </strong>
            </div>

            <div>
              <span>STATUS</span>
              <strong className="green">
                TRACKED
              </strong>
            </div>
          </div>

          <div className="selected-note">
            Reference orbital path displayed
            from current telemetry position.
          </div>
        </div>
      )}

      {/* =========================
          ISS PANEL
      ========================== */}

      {telemetry.iss && (
        <div className="iss-panel">
          <div className="iss-panel-title">
            <span className="iss-live-dot" />
            ISS LIVE POSITION
          </div>

          <div className="iss-data">
            <span>
              LAT{" "}
              {Number(
                telemetry.iss.lat
              ).toFixed(2)}
              °
            </span>

            <span>
              LON{" "}
              {Number(
                telemetry.iss.lon
              ).toFixed(2)}
              °
            </span>

            <span>
              ALT{" "}
              {Number(
                telemetry.iss.alt
              ).toFixed(2)}
              km
            </span>
          </div>
        </div>
      )}

      {/* =========================
          BOTTOM STATUS BAR
      ========================== */}

      <div className="tracker-bottom">
        <div>
          <span>TRACKING MODE</span>
          <strong>{viewMode}</strong>
        </div>

        <div>
          <span>DATA SOURCE</span>
          <strong>LIVE API</strong>
        </div>

        <div>
          <span>OBJECTS</span>
          <strong>
            {telemetry.debrisCount}
          </strong>
        </div>

        <div>
          <span>STATUS</span>
          <strong
            className={
              telemetry.connected
                ? "green"
                : "red"
            }
          >
            {telemetry.connected
              ? "OPERATIONAL"
              : "OFFLINE"}
          </strong>
        </div>
      </div>

      {/* =========================
          ERROR
      ========================== */}

      {telemetry.error && (
        <div className="tracker-error">
          <span>!</span>
          {telemetry.error}
        </div>
      )}
    </div>
  );
};

export default EarthScene;
